  await page.click('#undoBtn'); await page.waitForTimeout(120);
  check('  ↶ で動かす前にもどる', [(await P()).startsWith('買い物\n牛乳 2本\nたまご\n［写真］\n'), (await ph()).al].join('|'), 'true|c');

