  check('  　辞書：聞き取った字の よみの候補（久司 → ひさじ も・西谷 → にしたに が先）', await page.evaluate(() => rkYomiAlts('久司', 8).includes('ひさじ') + ' / ' + rkYomiAlts('西谷', 8)[0]), 'true / にしたに');

