        if (!p.steps.length) { out.bad.push(u.id + ':ヒントなし'); break; }
        const v = S.fromSpeech(p, S.sayAnswer(p));
        if (!v || !S.check(p, v).ok) { out.bad.push(u.id + ':声 ' + S.sayAnswer(p)); break; }
        const wv = p.ans.slice(), n0 = S.parseBlank(p.kinds[0], wv[0]);
